// F05_프로모션_대상_고객_선정 → 노드 "프로모션 대상 조건 적용" 의 코드 전체 (이슈 #26)
//
// 바뀐 점
// 1. 문서의 설명 문구가 그대로 조건이 된 경우를 걸러 낸다.
//    "Galaxy 전 단말" → 갤럭시 브랜드 조건, "대상 요금제"·"KT 판매 휴대폰" → 자동 판단하지 않는 조건
// 2. 브랜드 조건은 고객의 현재 기기와도 비교한다. 통신사 이름(KT)은 브랜드 조건으로 쓰지 않는다.
// 3. 관심 키워드는 고객을 탈락시키지 않고, 맞으면 선정 사유에만 적는다.
// 4. 자동으로 판단할 조건이 하나도 남지 않는 프로모션은(예: "KT 고객 누구나")
//    마케팅·재연락에 동의한 고객 전체를 대상으로 한다. 아래 BROAD_PROMOTION_TARGETS_ALL 로 끌 수 있다.

const BROAD_PROMOTION_TARGETS_ALL = true;

const results = [];

// 프로모션 기본 정보
const promotion = $('프로모션 정보 조회').first().json;

// 최종 타겟팅 규칙
const rules = $('대상 선정 조건 확정').first().json.output ?? {};


// --------------------------------
// 공통 함수
// --------------------------------
function toText(value) {
  if (value == null) return '';
  if (Array.isArray(value)) return value.join(' ');
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

function compact(value) {
  return toText(value).toLowerCase().replace(/\s+/g, '');
}

function list(value) {
  return Array.isArray(value)
    ? value.filter((v) => typeof v === 'string' && v.trim() !== '')
    : [];
}


// --------------------------------
// 브랜드. 같은 브랜드를 가리키는 여러 표기를 하나로 본다.
// --------------------------------
const BRANDS = [
  { name: '갤럭시', words: ['galaxy', '갤럭시', 'samsung', '삼성'] },
  { name: '아이폰', words: ['iphone', '아이폰', 'apple', '애플'] },
];

function brandOf(text) {
  const t = compact(text);
  return BRANDS.find((brand) => brand.words.some((w) => t.includes(w))) ?? null;
}

// 통신사 이름은 브랜드 조건이 아니다.
const CARRIER = /^(kt|케이티|skt|sk텔레콤|lgu\+?|lg유플러스|유플러스)$/;


// --------------------------------
// 기기 키워드 분류
//   model : 특정 모델·시리즈 (Galaxy Z Fold8, Galaxy A37, iPhone 17 Pro)
//   brand : 브랜드 전체 (Galaxy 전 단말)
//   none  : 자동으로 판단할 수 없는 설명 문구 (KT 판매 휴대폰, 5G/LTE 휴대폰, SIM)
// --------------------------------
const DEVICE_FILLER = /kt|케이티|다이렉트샵|다이렉트|판매|대상|전체|전단말|전기종|전모델|전제품|모든|단말기|단말|휴대폰|스마트폰|핸드폰|기기|모델|시리즈|제품|등|및|5g|lte|sim|usim|esim|유심|지원|미수령|지원금|자급제|기존|신규|\/|,|·|\(|\)/g;

function classifyDevice(keyword) {
  const raw = compact(keyword);
  const brand = brandOf(raw);
  let rest = raw;
  for (const b of BRANDS) for (const w of b.words) rest = rest.split(w).join('');
  rest = rest.replace(DEVICE_FILLER, '');
  // 브랜드 이름과 설명 문구를 빼고도 글자가 남으면 모델 이름이 있는 것이다.
  if (rest.length >= 2) return { type: 'model', keyword, brand };
  if (brand) return { type: 'brand', keyword, brand };
  return { type: 'none', keyword };
}

// 모델 이름을 고객 글에서 찾을 때 쓰는 여러 형태.
// "Galaxy Z Fold8" → galaxyzfold8, zfold8, fold8
function modelForms(keyword) {
  const full = compact(keyword);
  const forms = new Set([full]);
  let rest = full;
  for (const b of BRANDS) for (const w of b.words) rest = rest.split(w).join('');
  if (rest.length >= 3) forms.add(rest);
  const tail = rest.replace(/^z/, '');
  if (tail.length >= 3 && /\d/.test(tail)) forms.add(tail);
  return [...forms];
}


// --------------------------------
// 요금제 키워드. 실제 요금제 이름이 들어 있을 때만 조건으로 쓴다.
// "대상 요금제", "월 69,000원 이상 요금제" 는 고객의 요금제 이름과 비교할 수 없다.
// --------------------------------
const PLAN_NAMES = ['초이스', '베이직', '요고', '스페셜', '심플', '슬림', '세이브', '프리미엄', '데이터on', '시니어', '주니어'];

function planTokens(keyword) {
  const raw = compact(keyword);
  return PLAN_NAMES.filter((name) => raw.includes(name)).map((name) => {
    // "요고61" 처럼 이름 뒤에 숫자가 붙으면 숫자까지 포함해 비교한다.
    const match = raw.match(new RegExp(name + '\\d+'));
    return match ? match[0] : name;
  });
}


// --------------------------------
// 관심 키워드에서 일반적인 표현 제외
// --------------------------------
const GENERIC_KEYWORDS = [
  '기기변경', '구매', '상담', '휴대폰', '스마트폰', '핸드폰', '프로모션',
  '요금제', '할인', '혜택', '변경', '교체', '고객', '신규', '가입'
];

function isGenericKeyword(keyword) {
  const k = compact(keyword).replace(/관심|희망|예정/g, '');
  return k.length < 2 || GENERIC_KEYWORDS.some((g) => k === g || k === g + '고객');
}


// --------------------------------
// 규칙 정리
// --------------------------------
// "Galaxy Z Fold8 Ultra / Fold8 / Flip8" 처럼 한 줄에 여러 기기가 적힌 경우 나눠서 본다.
const rawDeviceKeywords = list(rules.target_device_keywords)
  .flatMap((keyword) => (/^\s*5g\s*\/\s*lte/i.test(keyword) ? [keyword] : keyword.split(/\s*[\/,·]\s*|\s+및\s+/)))
  .map((keyword) => keyword.trim())
  .filter(Boolean);
const rawPlanKeywords = list(rules.target_plan_keywords);
const rawBrandKeywords = list(rules.preferred_brand_keywords);
const rawInterestKeywords = list(rules.interest_keywords);

const devices = rawDeviceKeywords.map(classifyDevice);
const modelKeywords = devices.filter((d) => d.type === 'model');

// 브랜드 조건: 브랜드 키워드 + "Galaxy 전 단말" 처럼 브랜드 전체를 가리킨 기기 키워드
const brandRules = [];
for (const keyword of rawBrandKeywords) {
  if (CARRIER.test(compact(keyword))) continue;
  const brand = brandOf(keyword);
  if (brand && !brandRules.includes(brand)) brandRules.push(brand);
}
for (const d of devices) {
  if (d.type === 'brand' && !brandRules.includes(d.brand)) brandRules.push(d.brand);
}

const planRules = [...new Set(rawPlanKeywords.flatMap(planTokens))];
const interestKeywords = rawInterestKeywords.filter((k) => !isGenericKeyword(k));

// 자동으로 판단하지 않은 조건. 직원이 확인할 수 있게 결과에 함께 적는다.
const skipped = [
  ...devices.filter((d) => d.type === 'none').map((d) => '대상 기기: ' + d.keyword),
  ...rawPlanKeywords.filter((k) => planTokens(k).length === 0).map((k) => '대상 요금제: ' + k),
];

const hasHardRule =
  rules.age_min != null ||
  rules.age_max != null ||
  rules.min_device_use_months != null ||
  modelKeywords.length > 0 ||
  brandRules.length > 0 ||
  planRules.length > 0;

// 문서에서 조건을 하나라도 읽었는지 (아무것도 읽지 못한 경우와 구분)
const hasAnyCondition =
  rawDeviceKeywords.length > 0 ||
  rawPlanKeywords.length > 0 ||
  rawBrandKeywords.length > 0 ||
  rawInterestKeywords.length > 0 ||
  list(rules.eligibility_notes).length > 0;

const targetAll = rules.target_all === true;

// 걸러 낼 조건이 없는 넓은 프로모션
const broad = !targetAll && !hasHardRule && hasAnyCondition && BROAD_PROMOTION_TARGETS_ALL;

// 조건을 전혀 읽지 못했거나, 넓은 프로모션을 전체 대상으로 하지 않기로 한 경우
if (!targetAll && !hasHardRule && !broad) {
  return [];
}

const eligibilityNotes = [...list(rules.eligibility_notes), ...skipped.map((s) => '확인 필요 - ' + s)];


// --------------------------------
// 고객별 조건 적용
// --------------------------------
for (const item of $input.all()) {
  const customer = item.json;

  // Always Output Data 등으로 빈 item이 들어오는 경우 방어
  if (!customer.customer_id) continue;

  const analysis = customer.analysis_data ?? {};
  let matched = true;
  const matchReasons = [];

  // 고객의 관심·분석을 합친 글
  const targetingText = compact(
    [
      customer.interests,
      customer.consultation_goal,
      customer.usage_pattern,
      customer.preferred_brand,
      analysis.analysis_summary,
      analysis.usage_profile,
      analysis.replacement_reason,
      analysis.preferred_product_group,
      analysis.important_features,
      analysis.recommendation_factors
    ]
      .filter((v) => v != null)
      .map(toText)
      .join(' ')
  );
  const currentDevice = compact(customer.current_device);

  if (targetAll) {
    matchReasons.push('전체 고객 대상 프로모션');
  } else if (broad) {
    matchReasons.push('대상 범위가 넓은 프로모션 (동의 고객 전체)');
  } else {
    // 1. 최소 나이
    if (rules.age_min != null) {
      if (customer.age == null || Number(customer.age) < Number(rules.age_min)) matched = false;
      else matchReasons.push(`최소 연령 ${rules.age_min}세 이상 충족`);
    }

    // 2. 최대 나이
    if (rules.age_max != null) {
      if (customer.age == null || Number(customer.age) > Number(rules.age_max)) matched = false;
      else matchReasons.push(`최대 연령 ${rules.age_max}세 이하 충족`);
    }

    // 3. 최소 기기 사용 기간
    if (rules.min_device_use_months != null) {
      if (
        customer.device_use_months == null ||
        Number(customer.device_use_months) < Number(rules.min_device_use_months)
      ) matched = false;
      else matchReasons.push(`기기 사용 ${rules.min_device_use_months}개월 이상 충족`);
    }

    // 4. 대상 모델: 고객이 그 모델에 관심을 보였는지
    if (modelKeywords.length > 0) {
      const hit = modelKeywords.find((d) => modelForms(d.keyword).some((form) => targetingText.includes(form)));
      if (!hit) matched = false;
      else matchReasons.push(`대상 기기 관심 조건 충족 (${hit.keyword})`);
    }

    // 5. 브랜드: 그 브랜드를 쓰고 있거나 관심을 보였는지
    if (brandRules.length > 0) {
      const hit = brandRules.find((brand) =>
        brand.words.some((w) => currentDevice.includes(w) || targetingText.includes(w))
      );
      if (!hit) matched = false;
      else matchReasons.push(`${hit.name} 사용·관심 조건 충족`);
    }

    // 6. 대상 요금제: 고객의 현재 요금제 이름과 비교
    if (planRules.length > 0) {
      const plan = compact(customer.current_plan);
      const hit = planRules.find((token) => plan.includes(token));
      if (!hit) matched = false;
      else matchReasons.push(`대상 요금제 조건 충족 (${hit})`);
    }
  }

  if (!matched) continue;

  // 관심 키워드는 탈락시키지 않고, 맞으면 사유에만 적는다.
  const interestHit = interestKeywords.find((k) => targetingText.includes(compact(k)));
  if (interestHit) matchReasons.push(`관심 조건 충족 (${interestHit})`);

  results.push({
    json: {
      customer_id: customer.customer_id,
      customer_name: customer.customer_name,
      phone: customer.phone,

      schedule_type: 'promotion',
      reference_date: promotion.valid_from ?? null,
      contact_reason: `${promotion.file_name || '프로모션'} 안내`,

      document_id: promotion.document_id ?? null,
      store_id: promotion.store_id ?? null,
      consultation_id: null,

      match_reasons: matchReasons,
      eligibility_notes: eligibilityNotes
    }
  });
}

return results;

const items = $input.all();

const seen = new Set();
const results = [];

for (const item of items) {
  const customer = item.json;

  // 필수값 확인
  if (!customer.customer_id) {
    continue;
  }

  if (!customer.document_id) {
    continue;
  }

  if (!customer.schedule_type) {
    continue;
  }

  // 고객 + 프로모션 기준 중복 제거
  const uniqueKey =
    `${customer.document_id}:${customer.customer_id}`;

  if (seen.has(uniqueKey)) {
    continue;
  }

  seen.add(uniqueKey);

  results.push({
    json: {
      customer_id: customer.customer_id,
      customer_name: customer.customer_name ?? null,
      phone: customer.phone ?? null,

      schedule_type: customer.schedule_type,

      reference_date: customer.reference_date ?? null,
      contact_reason: customer.contact_reason ?? null,

      document_id: customer.document_id,

      // null 허용: null이면 전 매장 대상
      store_id: customer.store_id ?? null,

      consultation_id: customer.consultation_id ?? null,

      match_reasons: Array.isArray(customer.match_reasons)
        ? customer.match_reasons
        : [],

      eligibility_notes: Array.isArray(customer.eligibility_notes)
        ? customer.eligibility_notes
        : []
    }
  });
}

return results;

const promotion = $('프로모션 정보 조회').first().json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-05',
      status: 'no_target',

      document_id: promotion.document_id ?? null,
      store_id: promotion.store_id ?? null,
      event_name: promotion.file_name ?? null,
      valid_from: promotion.valid_from ?? null,
      valid_until: promotion.valid_until ?? null,

      target_count: 0,
      matches: []
    }
  }
];

const customers = $input.all().map(item => item.json);
const promotion = $('프로모션 정보 조회').first().json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-05',
      status: 'targeted',

      document_id: promotion.document_id ?? null,
      store_id: promotion.store_id ?? null,
      event_name: promotion.file_name ?? null,
      valid_from: promotion.valid_from ?? null,
      valid_until: promotion.valid_until ?? null,

      target_count: customers.length,

      matches: customers.map(customer => ({
        customer_id: customer.customer_id,
        customer_name: customer.customer_name ?? null,
        phone: customer.phone ?? null,
        schedule_type: customer.schedule_type ?? 'promotion',
        reference_date: customer.reference_date ?? null,
        contact_reason: customer.contact_reason ?? null,
        consultation_id: customer.consultation_id ?? null,
        match_reasons: customer.match_reasons ?? [],
        eligibility_notes: customer.eligibility_notes ?? []
      }))
    }
  }
];

const input = $('프로모션 입력값 확인').first().json;

return [
  {
    json: {
      success: false,
      feature_id: 'F-05',
      status: 'promotion_not_found',

      document_id: input.document_id ?? null,
      store_id: input.store_id ?? null,

      target_count: 0,
      matches: []
    }
  }
];
